package com.kgsat.payment.repository; import org.springframework.stereotype.Repository; import java.util.concurrent.*; @Repository public class ProcessedOrderRepository { private final ConcurrentHashMap<String,Boolean> processed=new ConcurrentHashMap<>(); public boolean claim(String id){return processed.putIfAbsent(id,Boolean.TRUE)==null;} public void release(String id){processed.remove(id);} }
